// Sample and hold: Sample, track or quantize one LFO using a separate trigger LFO. The stored value survives compatible source edits.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  oscillator as oscillatorDefinition,
  lfo as lfoDefinition,
  sampleHold as sampleHoldDefinition,
  modulatedGain as modulatedGainDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    oscillator_waveform: {
      "path": "/primitives/sample-hold/node/0",
      "label": "Waveform",
      "group": "Oscillator",
      "min": 0,
      "max": 4,
      "default": 0,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend"
      ]
    },
    oscillator_frequency: {
      "path": "/primitives/sample-hold/node/1",
      "label": "Frequency",
      "group": "Oscillator",
      "min": 20,
      "max": 16000,
      "default": 220
    },
    oscillator_level: {
      "path": "/primitives/sample-hold/node/2",
      "label": "Level",
      "group": "Oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    source_waveform: {
      "path": "/primitives/sample-hold/source/0",
      "label": "Waveform",
      "group": "LFO",
      "min": 0,
      "max": 2,
      "default": 0,
      "choices": [
        "Sine",
        "Triangle",
        "Square"
      ]
    },
    source_rate: {
      "path": "/primitives/sample-hold/source/1",
      "label": "Rate",
      "group": "LFO",
      "min": 0.05,
      "max": 20,
      "default": 2
    },
    clock_waveform: {
      "path": "/primitives/sample-hold/clock/0",
      "label": "Waveform",
      "group": "LFO",
      "min": 0,
      "max": 2,
      "default": 2,
      "choices": [
        "Sine",
        "Triangle",
        "Square"
      ]
    },
    clock_rate: {
      "path": "/primitives/sample-hold/clock/1",
      "label": "Rate",
      "group": "LFO",
      "min": 0.05,
      "max": 20,
      "default": 7
    },
    hold_mode: {
      "path": "/primitives/sample-hold/hold/0",
      "label": "Mode",
      "group": "Sample / hold",
      "min": 0,
      "max": 2,
      "default": 0,
      "choices": [
        "Sample",
        "Track",
        "12-step"
      ]
    },
    gain_base: {
      "path": "/primitives/sample-hold/gain/0",
      "label": "Base",
      "group": "CV gain",
      "min": 0,
      "max": 2,
      "default": 0.5
    },
    gain_depth: {
      "path": "/primitives/sample-hold/gain/1",
      "label": "Depth",
      "group": "CV gain",
      "min": -2,
      "max": 2,
      "default": 0.4
    },
  };

  // Audio inputs and outputs — generated sound; no audio input is needed.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const oscillator = graph.add(oscillatorDefinition.type, {"id":4});
  graph.registerInstance('/primitives/sample-hold/node', oscillator);
  oscillator.parameter('waveform').expose(controls.oscillator_waveform);
  oscillator.parameter('frequency').expose(controls.oscillator_frequency);
  oscillator.parameter('level').expose(controls.oscillator_level);

  const source = graph.add(lfoDefinition.type, {"id":5});
  graph.registerInstance('/primitives/sample-hold/source', source);
  source.parameter('waveform').expose(controls.source_waveform);
  source.parameter('rate').expose(controls.source_rate);

  const clock = graph.add(lfoDefinition.type, {"id":6});
  graph.registerInstance('/primitives/sample-hold/clock', clock);
  clock.parameter('waveform').expose(controls.clock_waveform);
  clock.parameter('rate').expose(controls.clock_rate);

  const hold = graph.add(sampleHoldDefinition.type, {"id":7});
  graph.registerInstance('/primitives/sample-hold/hold', hold);
  hold.parameter('mode').expose(controls.hold_mode);

  const gain = graph.add(modulatedGainDefinition.type, {"id":8});
  graph.registerInstance('/primitives/sample-hold/gain', gain);
  gain.parameter('base').expose(controls.gain_base);
  gain.parameter('depth').expose(controls.gain_depth);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(oscillator.output('out'), gain.input('audio'));
  graph.connect(source.output('out'), hold.input('cv'));
  graph.connect(clock.output('uni'), hold.input('trigger'));
  graph.connect(hold.output('out'), gain.input('cv'));
  graph.connect(gain.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.oscillator_waveform,
    controls.oscillator_frequency,
    controls.oscillator_level,
    controls.source_waveform,
    controls.source_rate,
    controls.clock_waveform,
    controls.clock_rate,
    controls.hold_mode,
    controls.gain_base,
    controls.gain_depth
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
